import test,{after,before}from"node:test";import assert from"node:assert/strict";import{existsSync}from"node:fs";import{symlink,unlink}from "./moduleLinkTestUtils.ts";import{resolve}from"node:path";import{convexTest}from"convex-test";import schema from"../convex/schema.ts";import{api}from"../convex/_generated/api.js";
import type{Id}from"../convex/_generated/dataModel";
const links=[["convex/_generated/server","server.js"],["convex/lib/auth","auth.ts"],["convex/lib/generalLedger","generalLedger.ts"],["convex/lib/generalLedgerRules","generalLedgerRules.ts"],["convex/lib/generalLedgerTemplate","generalLedgerTemplate.ts"],["convex/lib/finance","finance.ts"],["convex/lib/documentNumbers","documentNumbers.ts"],["convex/lib/permissions","permissions.ts"],["shared/businessRules","businessRules.ts"]]as const;before(async()=>{for(const[p,t]of links)if(!existsSync(resolve(p)))await symlink(t,resolve(p))});after(async()=>{for(const[p]of links)if(existsSync(resolve(p)))await unlink(resolve(p))});const modules={"../convex/_generated/api.js":()=>import("../convex/_generated/api.js"),"../convex/_generated/server.js":()=>import("../convex/_generated/server.js"),"../convex/generalLedger.ts":()=>import("../convex/generalLedger.ts"),"../convex/finance.ts":()=>import("../convex/finance.ts"),"../convex/financialBridgeHarness.ts":()=>import("./financialBridgeHarness.ts")};async function fixture(){const raw=convexTest(schema,modules);const branchId=await raw.run(async c=>{const b=await c.db.insert("branches",{name:"الرئيسي",address:"القاهرة",isActive:true});await c.db.insert("userProfiles",{userId:"admin",tokenIdentifier:"admin",name:"مدير",role:"admin",branchId:b,permissions:[],isActive:true});return b});return{raw,t:raw.withIdentity({subject:"admin",tokenIdentifier:"admin"}),branchId}}
async function initialized(cutoverDate="2026-01-01"){const e=await fixture();await e.t.mutation(api.generalLedger.initialize,{cutoverDate,requestId:"init"});return e}
async function account(e:Awaited<ReturnType<typeof fixture>>,code:string){const row=(await e.t.query(api.generalLedger.chart,{activeOnly:false})).find(x=>x.code===code);assert.ok(row);return row._id}
async function ready(date="2026-01-01"){const e=await initialized(date);await e.t.mutation(api.generalLedger.createOrOpenPeriod,{periodKey:date.slice(0,7)});await e.t.mutation(api.generalLedger.confirmOpening,{branchId:e.branchId,openingDate:date,isZeroOpening:true,lines:[],requestId:"opening"});return e}
async function post(e:Awaited<ReturnType<typeof fixture>>,requestId:string,date="2026-01-01",amount=100){return e.t.mutation(api.generalLedger.postManualJournal,{branchId:e.branchId,date,memo:`قيد ${requestId}`,requestId,lines:[{accountId:await account(e,"1110"),debit:amount,credit:0},{accountId:await account(e,"4100"),debit:0,credit:amount}]})}
async function snapshot(e:Awaited<ReturnType<typeof fixture>>){return e.raw.run(async c=>{const sort=<T extends{_id:string}>(rows:T[])=>rows.sort((a,b)=>String(a._id).localeCompare(String(b._id)));return{chartOfAccounts:sort(await c.db.query("chartOfAccounts").collect()),generalLedgerOpenings:sort(await c.db.query("generalLedgerOpenings").collect()),accountingPeriods:sort(await c.db.query("accountingPeriods").collect()),journalEntries:sort(await c.db.query("journalEntries").collect()),journalLines:sort(await c.db.query("journalLines").collect()),generalLedgerAccountBalances:sort(await c.db.query("generalLedgerAccountBalances").collect()),generalLedgerPeriodBalances:sort(await c.db.query("generalLedgerPeriodBalances").collect()),generalLedgerDailyBalances:sort(await c.db.query("generalLedgerDailyBalances").collect()),documentCounters:sort(await c.db.query("documentCounters").collect()),auditLogs:sort(await c.db.query("auditLogs").collect()),payments:sort(await c.db.query("payments").collect())}})}
async function rejectUnchanged(e:Awaited<ReturnType<typeof fixture>>,operation:Promise<unknown>,pattern?:RegExp){const before=await snapshot(e);await assert.rejects(operation,pattern);assert.deepEqual(await snapshot(e),before)}
async function addUser(e:Awaited<ReturnType<typeof fixture>>,userId:string,role:"admin"|"manager"|"accountant"|"viewer"|"sales"|"shipping",branchId=e.branchId){await e.raw.run(c=>c.db.insert("userProfiles",{userId,tokenIdentifier:userId,name:userId,role,branchId,permissions:[],isActive:true}));return e.raw.withIdentity({subject:userId,tokenIdentifier:userId})}
async function addBranch(e:Awaited<ReturnType<typeof fixture>>,name="الثاني"){const branchId=await e.raw.run(c=>c.db.insert("branches",{name,address:"الإسكندرية",isActive:true}));await e.t.mutation(api.generalLedger.confirmOpening,{branchId,openingDate:"2026-01-01",isZeroOpening:true,lines:[],requestId:`opening-${name}`});return branchId}
async function postAt(e:Awaited<ReturnType<typeof fixture>>,branchId:typeof e.branchId,requestId:string,date:string,amount:number,identity=e.t){return identity.mutation(api.generalLedger.postManualJournal,{branchId,date,memo:`قيد ${requestId}`,requestId,lines:[{accountId:await account(e,"1110"),debit:amount,credit:0},{accountId:await account(e,"4100"),debit:0,credit:amount}]})}
const keys=(value:object)=>Object.keys(value).sort();
const page={numItems:10,cursor:null};
test("GLF-01 initialize settings and chart",async()=>{const e=await fixture();const r=await e.t.mutation(api.generalLedger.initialize,{cutoverDate:"2026-01-01",requestId:"init"});const status=await e.t.query(api.generalLedger.status,{});assert.equal(r.status,"foundation_ready");assert.equal(status.operationalPostingEnabled,false)});
