test("GLF-04 template hierarchy system keys normal sides",async()=>{const e=await initialized();const c=await e.t.query(api.generalLedger.chart,{activeOnly:false});assert.equal(c.find(x=>x.code==="4190")?.normalSide,"debit");assert.equal(c.find(x=>x.code==="1000")?.isPosting,false)});
test("GLF-05 normalized duplicate account code",async()=>{const e=await initialized(),parent=await account(e,"6000"),before=await snapshot(e);const id=await e.t.mutation(api.generalLedger.createAccount,{code:"63 00",nameAr:"مصروف",parentId:parent,normalSide:"debit",isContra:false});const created=(await e.t.query(api.generalLedger.chart,{activeOnly:false})).find(x=>x._id===id);assert.equal(created?.code,"6300");const accepted=await snapshot(e);assert.equal(accepted.chartOfAccounts.length,before.chartOfAccounts.length+1);assert.equal(accepted.auditLogs.length,before.auditLogs.length+1);await rejectUnchanged(e,e.t.mutation(api.generalLedger.createAccount,{code:"6300",nameAr:"مكرر",parentId:parent,normalSide:"debit",isContra:false}),/مكرر/);await rejectUnchanged(e,e.t.mutation(api.generalLedger.createAccount,{code:" 6 3 0 0 ",nameAr:"مكرر آخر",parentId:parent,normalSide:"debit",isContra:false}),/مكرر/);const chart=await e.t.query(api.generalLedger.chart,{activeOnly:false});assert.equal(chart.filter(x=>x.code==="6300").length,1);assert.deepEqual((await snapshot(e)).chartOfAccounts,accepted.chartOfAccounts);assert.deepEqual((await snapshot(e)).auditLogs,accepted.auditLogs)});
test("GLF-06 invalid parent hierarchy and natural side",async()=>{const e=await initialized(),posting=await account(e,"1110"),parent=await account(e,"6000");await rejectUnchanged(e,e.t.mutation(api.generalLedger.createAccount,{code:"6301",nameAr:"   ",parentId:parent,normalSide:"debit",isContra:false}));await rejectUnchanged(e,e.t.mutation(api.generalLedger.createAccount,{code:"6302",nameAr:"Posting parent",parentId:posting,normalSide:"debit",isContra:false}));const inactive=await e.t.mutation(api.generalLedger.createAccount,{code:"6303",nameAr:"أب مخصص",parentId:parent,normalSide:"debit",isContra:false});await e.t.mutation(api.generalLedger.deactivateAccount,{accountId:inactive});await rejectUnchanged(e,e.t.mutation(api.generalLedger.createAccount,{code:"6304",nameAr:"Inactive parent",parentId:inactive,normalSide:"debit",isContra:false}));await rejectUnchanged(e,e.t.mutation(api.generalLedger.createAccount,{code:"6305",nameAr:"Wrong normalSide",parentId:parent,normalSide:"credit",isContra:false}));const id=await e.t.mutation(api.generalLedger.createAccount,{code:"6306",nameAr:"Contra",parentId:parent,normalSide:"credit",isContra:true});const row=(await e.t.query(api.generalLedger.chart,{activeOnly:false})).find(x=>x._id===id);assert.deepEqual({accountClass:row?.accountClass,normalSide:row?.normalSide,isContra:row?.isContra,parentId:row?.parentId},{accountClass:"expense",normalSide:"credit",isContra:true,parentId:parent});assert.ok((await snapshot(e)).auditLogs.some(x=>x.recordId===String(id)))});
test("GLF-07 custom account deactivation history",async()=>{const e=await ready(),parent=await account(e,"6000"),custom=await e.t.mutation(api.generalLedger.createAccount,{code:"6301",nameAr:"مصروف خاص",parentId:parent,normalSide:"debit",isContra:false}),cash=await account(e,"1110");const entry=await e.t.mutation(api.generalLedger.postManualJournal,{branchId:e.branchId,date:"2026-01-01",memo:"historical 75",requestId:"custom75",lines:[{accountId:custom,debit:75,credit:0},{accountId:cash,debit:0,credit:75}]});await e.t.mutation(api.generalLedger.deactivateAccount,{accountId:custom});const stored=await e.raw.run(c=>c.db.get(custom));assert.equal(stored?.isActive,false);assert.ok(stored?.deactivatedAt);assert.equal(stored?.deactivatedBy,"admin");const details=await e.t.query(api.generalLedger.entryDetails,{entryId:entry._id});assert.equal(details.lines[0].accountCode,"6301");assert.equal(details.lines[0].accountName,"مصروف خاص");const stable=await snapshot(e);await assert.rejects(e.t.mutation(api.generalLedger.postManualJournal,{branchId:e.branchId,date:"2026-01-01",memo:"rejected inactive",requestId:"inactive75",lines:[{accountId:custom,debit:75,credit:0},{accountId:cash,debit:0,credit:75}]}),/الحساب/);assert.deepEqual(await snapshot(e),stable);assert.equal((await e.t.query(api.generalLedger.entryDetails,{entryId:entry._id})).lineCount,2)});
test("GLF-08 inactive nonposting rejection rollback",async()=>{const a=await ready(),cash=await account(a,"1110");await rejectUnchanged(a,a.t.mutation(api.generalLedger.postManualJournal,{branchId:a.branchId,date:"2026-01-01",memo:"nonposting",requestId:"nonposting",lines:[{accountId:await account(a,"6000"),debit:10,credit:0},{accountId:cash,debit:0,credit:10}]}),/الحساب/);const b=await ready(),parent=await account(b,"6000"),inactive=await b.t.mutation(api.generalLedger.createAccount,{code:"6308",nameAr:"inactive",parentId:parent,normalSide:"debit",isContra:false});await b.t.mutation(api.generalLedger.deactivateAccount,{accountId:inactive});const before=await snapshot(b);await assert.rejects(b.t.mutation(api.generalLedger.postManualJournal,{branchId:b.branchId,date:"2026-01-01",memo:"inactive",requestId:"inactive",lines:[{accountId:inactive,debit:10,credit:0},{accountId:await account(b,"1110"),debit:0,credit:10}]}),/الحساب/);const after=await snapshot(b);assert.deepEqual({journalEntries:after.journalEntries,journalLines:after.journalLines,generalLedgerAccountBalances:after.generalLedgerAccountBalances,generalLedgerPeriodBalances:after.generalLedgerPeriodBalances,documentCounters:after.documentCounters,auditLogs:after.auditLogs,payments:after.payments},{journalEntries:before.journalEntries,journalLines:before.journalLines,generalLedgerAccountBalances:before.generalLedgerAccountBalances,generalLedgerPeriodBalances:before.generalLedgerPeriodBalances,documentCounters:before.documentCounters,auditLogs:before.auditLogs,payments:before.payments})});
test("GLF-09 balanced nonzero opening",async()=>{const e=await initialized();await e.t.mutation(api.generalLedger.createOrOpenPeriod,{periodKey:"2026-01"});const ids=await Promise.all(["1110","1200","2100","3200"].map(code=>account(e,code)));const opening=await e.t.mutation(api.generalLedger.confirmOpening,{branchId:e.branchId,openingDate:"2026-01-01",isZeroOpening:false,requestId:"opening1300",lines:[{accountId:ids[0],debit:1000,credit:0},{accountId:ids[1],debit:300,credit:0},{accountId:ids[2],debit:0,credit:500},{accountId:ids[3],debit:0,credit:800}]});const state=await snapshot(e),entry=state.journalEntries[0];assert.equal(opening.openingEntryId,entry._id);assert.deepEqual({number:entry.entryNumber,debit:entry.totalDebit,credit:entry.totalCredit,count:entry.lineCount,source:entry.sourceType,status:entry.status},{number:"JRN-2026-00001",debit:1300,credit:1300,count:4,source:"opening",status:"posted"});assert.deepEqual(state.journalLines.map(x=>[x.debit,x.credit]),[[1000,0],[300,0],[0,500],[0,800]]);assert.deepEqual(state.generalLedgerAccountBalances.map(x=>x.netDebitBalance).sort((a,b)=>a-b),[-800,-500,300,1000]);assert.equal(state.generalLedgerPeriodBalances.length,4);assert.ok(state.generalLedgerPeriodBalances.every(x=>x.periodKey==="2026-01"));assert.deepEqual({key:state.documentCounters[0].key,nextValue:state.documentCounters[0].nextValue},{key:"journal:2026",nextValue:2});assert.equal(state.auditLogs.filter(x=>x.action==="post").length,1);assert.equal(state.generalLedgerOpenings.length,1);assert.equal(state.payments.length,0)});
test("GLF-10 zero opening without journal",async()=>{const e=await initialized(),args={branchId:e.branchId,openingDate:"2026-01-01",isZeroOpening:true,lines:[],requestId:"zero"};const first=await e.t.mutation(api.generalLedger.confirmOpening,args),retry=await e.t.mutation(api.generalLedger.confirmOpening,args),state=await snapshot(e);assert.equal(first._id,retry._id);assert.equal(state.generalLedgerOpenings.length,1);assert.equal(first.isZeroOpening,true);assert.equal(first.openingEntryId,undefined);assert.equal(state.journalEntries.length,0);assert.equal(state.journalLines.length,0);assert.equal(state.generalLedgerAccountBalances.length,0);assert.equal(state.generalLedgerPeriodBalances.length,0);assert.equal(state.documentCounters.filter(x=>x.documentType==="journal").length,0);assert.equal(state.auditLogs.filter(x=>x.action==="post").length,0);assert.equal(state.payments.length,0)});
test("GLF-11 duplicate opening idempotency",async()=>{const a=await initialized(),args={branchId:a.branchId,openingDate:"2026-01-01",isZeroOpening:true,lines:[],requestId:"retry"};const first=await a.t.mutation(api.generalLedger.confirmOpening,args),retry=await a.t.mutation(api.generalLedger.confirmOpening,args);assert.equal(first._id,retry._id);await rejectUnchanged(a,a.t.mutation(api.generalLedger.confirmOpening,{...args,openingDate:"2026-01-02"}),/مختلفة/);await rejectUnchanged(a,a.t.mutation(api.generalLedger.confirmOpening,{...args,requestId:"new-request"}),/افتتاح/);const historical=await initialized();await historical.raw.run(c=>c.db.insert("journalEntries",{entryNumber:"JRN-2025-00001",branchId:historical.branchId,entryDate:"2025-12-31",periodKey:"2025-12",sourceType:"manual",status:"posted",memo:"historical manual",totalDebit:0,totalCredit:0,lineCount:0,requestId:"historical",idempotencyKey:"historical",requestFingerprint:"historical",postedAt:1,postedBy:"admin"}));const before=await snapshot(historical);await assert.rejects(historical.t.mutation(api.generalLedger.confirmOpening,{branchId:historical.branchId,openingDate:"2026-01-01",isZeroOpening:true,lines:[],requestId:"historical-opening"}),/حركة يدوية/);assert.deepEqual(await snapshot(historical),before)});
test("GLF-12 cutover and ISO opening date",async()=>{const e=await initialized("2026-01-10");await rejectUnchanged(e,e.t.mutation(api.generalLedger.confirmOpening,{branchId:e.branchId,openingDate:"2026-02-30",isZeroOpening:true,lines:[],requestId:"invalid-date"}));await rejectUnchanged(e,e.t.mutation(api.generalLedger.confirmOpening,{branchId:e.branchId,openingDate:"10/01/2026",isZeroOpening:true,lines:[],requestId:"invalid-iso"}));await rejectUnchanged(e,e.t.mutation(api.generalLedger.confirmOpening,{branchId:e.branchId,openingDate:"2026-01-09",isZeroOpening:true,lines:[],requestId:"before"}),/القطع/);await e.t.mutation(api.generalLedger.confirmOpening,{branchId:e.branchId,openingDate:"2026-01-10",isZeroOpening:true,lines:[],requestId:"at"});await e.t.mutation(api.generalLedger.createOrOpenPeriod,{periodKey:"2026-01"});const cash=await account(e,"1110"),sales=await account(e,"4100"),stable=await snapshot(e);await assert.rejects(e.t.mutation(api.generalLedger.postManualJournal,{branchId:e.branchId,date:"2026-01-09",memo:"before",requestId:"manual-before",lines:[{accountId:cash,debit:1,credit:0},{accountId:sales,debit:0,credit:1}]}),/القطع/);assert.deepEqual(await snapshot(e),stable);const entry=await e.t.mutation(api.generalLedger.postManualJournal,{branchId:e.branchId,date:"2026-01-10",memo:"at",requestId:"manual-at",lines:[{accountId:cash,debit:1,credit:0},{accountId:sales,debit:0,credit:1}]});assert.equal(entry.periodKey,"2026-01")});
test("GLF-13 balanced manual posting balances",async()=>{const e=await ready(),cash=await account(e,"1110"),sales=await account(e,"4100"),entry=await e.t.mutation(api.generalLedger.postManualJournal,{branchId:e.branchId,date:"2026-01-01",memo:"manual 250",requestId:"manual250",lines:[{accountId:cash,debit:250,credit:0,description:"cash"},{accountId:sales,debit:0,credit:250,description:"sales"}]});const s=await snapshot(e);assert.deepEqual({debit:entry.totalDebit,credit:entry.totalCredit,count:entry.lineCount},{debit:250,credit:250,count:2});assert.deepEqual(s.journalLines.map(x=>[x.lineNumber,x.accountCodeSnapshot,x.normalSideSnapshot,x.debit,x.credit]),[[1,"1110","debit",250,0],[2,"4100","credit",0,250]]);assert.deepEqual(s.generalLedgerAccountBalances.map(x=>x.netDebitBalance).sort((a,b)=>a-b),[-250,250]);assert.deepEqual(s.generalLedgerPeriodBalances.map(x=>x.netDebitMovement).sort((a,b)=>a-b),[-250,250]);assert.equal(s.documentCounters[0].nextValue,2);assert.equal(s.auditLogs.filter(x=>x.action==="post").length,1);assert.equal(s.payments.length,0)});
test("GLF-14 unbalanced atomic rollback",async()=>{const e=await ready();await rejectUnchanged(e,e.t.mutation(api.generalLedger.postManualJournal,{branchId:e.branchId,date:"2026-01-01",memo:"unbalanced",requestId:"100-v-99.99",lines:[{accountId:await account(e,"1110"),debit:100,credit:0},{accountId:await account(e,"4100"),debit:0,credit:99.99}]}),/متوازن/)});
test("GLF-15 invalid monetary values",async()=>{const e=await ready(),cash=await account(e,"1110"),sales=await account(e,"4100");const reject=async(requestId:string,lines:{accountId:typeof cash;debit:number;credit:number}[])=>rejectUnchanged(e,e.t.mutation(api.generalLedger.postManualJournal,{branchId:e.branchId,date:"2026-01-01",memo:requestId,requestId,lines}));await reject("fraction-1.001",[{accountId:cash,debit:1.001,credit:0},{accountId:sales,debit:0,credit:1.001}]);await reject("negative",[{accountId:cash,debit:-1,credit:0},{accountId:sales,debit:0,credit:-1}]);await reject("zero",[{accountId:cash,debit:0,credit:0},{accountId:sales,debit:0,credit:0}]);await reject("NaN",[{accountId:cash,debit:Number.NaN,credit:0},{accountId:sales,debit:0,credit:Number.NaN}]);await reject("Infinity",[{accountId:cash,debit:Number.POSITIVE_INFINITY,credit:0},{accountId:sales,debit:0,credit:Number.POSITIVE_INFINITY}]);await reject("both-sides",[{accountId:cash,debit:10,credit:10},{accountId:sales,debit:0,credit:10}]);await reject("both-zero",[{accountId:cash,debit:0,credit:0},{accountId:sales,debit:0,credit:0}]);await reject("one-line",[{accountId:cash,debit:10,credit:0}]);await reject("no-debit",[{accountId:cash,debit:0,credit:10},{accountId:sales,debit:0,credit:10}]);await reject("no-credit",[{accountId:cash,debit:10,credit:0},{accountId:sales,debit:10,credit:0}]);await reject("duplicate-line",[{accountId:cash,debit:10,credit:0},{accountId:cash,debit:10,credit:0},{accountId:sales,debit:0,credit:20}])});
test("GLF-16 server totals and snapshots",async()=>{const e=await ready(),cash=await account(e,"1110"),expense=await account(e,"6200"),sales=await account(e,"4100"),entry=await e.t.mutation(api.generalLedger.postManualJournal,{branchId:e.branchId,date:"2026-01-01",memo:"multi",requestId:"multi",lines:[{accountId:cash,debit:100,credit:0},{accountId:expense,debit:50,credit:0},{accountId:sales,debit:0,credit:150}]});assert.deepEqual([entry.totalDebit,entry.totalCredit,entry.lineCount],[150,150,3]);await e.raw.run(c=>c.db.patch(cash,{code:"1119",normalizedCode:"1119",nameAr:"نقدية معدلة"}));const current=await e.raw.run(c=>c.db.get(cash)),details=await e.t.query(api.generalLedger.entryDetails,{entryId:entry._id}),print=await e.t.query(api.generalLedger.entryForPrint,{entryId:entry._id});assert.equal(current?.nameAr,"نقدية معدلة");for(const dto of [details,print]){assert.equal(dto.lines[0].accountCode,"1110");assert.notEqual(dto.lines[0].accountName,"نقدية معدلة");assert.equal(dto.lines[0].normalSide,"debit");assert.deepEqual([dto.totalDebit,dto.totalCredit,dto.lineCount],[150,150,3])}});
test("GLF-17 first yearly JRN number",async()=>{const e=await ready(),cash=await account(e,"1110"),sales=await account(e,"4100"),args={branchId:e.branchId,date:"2026-01-01",memo:"first",requestId:"first",lines:[{accountId:cash,debit:100,credit:0},{accountId:sales,debit:0,credit:100}]},entry=await e.t.mutation(api.generalLedger.postManualJournal,args),retry=await e.t.mutation(api.generalLedger.postManualJournal,args);assert.equal(entry.entryNumber,"JRN-2026-00001");assert.equal(retry._id,entry._id);const counter=await e.raw.run(c=>c.db.query("documentCounters").withIndex("by_key",q=>q.eq("key","journal:2026")).unique()),byNumber=await e.raw.run(c=>c.db.query("journalEntries").withIndex("by_number",q=>q.eq("entryNumber","JRN-2026-00001")).unique());assert.deepEqual({key:counter?.key,documentType:counter?.documentType,year:counter?.year,nextValue:counter?.nextValue},{key:"journal:2026",documentType:"journal",year:2026,nextValue:2});assert.equal(byNumber?._id,entry._id)});
test("GLF-18 historical collision concurrency year",async()=>{const clean=await ready(),first=await clean.t.mutation(api.generalLedger.postManualJournal,{branchId:clean.branchId,date:"2026-01-01",memo:"clean",requestId:"clean",lines:[{accountId:await account(clean,"1110"),debit:100,credit:0},{accountId:await account(clean,"4100"),debit:0,credit:100}]});assert.equal(first.entryNumber,"JRN-2026-00001");assert.equal((await snapshot(clean)).documentCounters[0].nextValue,2);const historical=await ready();await historical.raw.run(async c=>{await c.db.insert("journalEntries",{entryNumber:"JRN-2025-00099",branchId:historical.branchId,entryDate:"2025-01-01",periodKey:"2025-01",sourceType:"manual",status:"posted",memo:"2025",totalDebit:0,totalCredit:0,lineCount:0,requestId:"h25",idempotencyKey:"h25",requestFingerprint:"h25",postedAt:1,postedBy:"admin"});await c.db.insert("journalEntries",{entryNumber:"JRN-2026-00007",branchId:historical.branchId,entryDate:"2026-01-01",periodKey:"2026-01",sourceType:"manual",status:"posted",memo:"00007",totalDebit:0,totalCredit:0,lineCount:0,requestId:"h7",idempotencyKey:"h7",requestFingerprint:"h7",postedAt:1,postedBy:"admin"})});assert.equal((await post(historical,"after-seven")).entryNumber,"JRN-2026-00008");assert.equal((await snapshot(historical)).documentCounters.find(x=>x.key==="journal:2026")?.nextValue,9);const collision=await ready();await collision.raw.run(async c=>{await c.db.insert("documentCounters",{key:"journal:2026",documentType:"journal",year:2026,nextValue:9,updatedAt:1});await c.db.insert("journalEntries",{entryNumber:"JRN-2026-00009",branchId:collision.branchId,entryDate:"2026-01-01",periodKey:"2026-01",sourceType:"manual",status:"posted",memo:"collision",totalDebit:0,totalCredit:0,lineCount:0,requestId:"h9",idempotencyKey:"h9",requestFingerprint:"h9",postedAt:1,postedBy:"admin"})});assert.equal((await post(collision,"skip-nine")).entryNumber,"JRN-2026-00010");assert.equal((await snapshot(collision)).documentCounters[0].nextValue,11);const optimistic=await ready();const pair=await Promise.all([post(optimistic,"optimistic-a"),post(optimistic,"optimistic-b")]);assert.deepEqual(pair.map(x=>x.entryNumber).sort(),["JRN-2026-00001","JRN-2026-00002"]);assert.equal(new Set(pair.map(x=>x.entryNumber)).size,2);const os=await snapshot(optimistic);assert.equal(os.documentCounters[0].nextValue,3);assert.equal(os.journalEntries.length,2);assert.equal(os.journalLines.length,4);assert.equal(os.generalLedgerAccountBalances.length,2);const years=await ready();await post(years,"year-2026");const counter2026=(await snapshot(years)).documentCounters.find(x=>x.key==="journal:2026")?.nextValue;await years.t.mutation(api.generalLedger.createOrOpenPeriod,{periodKey:"2027-01"});const y=await post(years,"year-2027","2027-01-01");assert.equal(y.entryNumber,"JRN-2027-00001");const counters=(await snapshot(years)).documentCounters;assert.equal(counters.find(x=>x.key==="journal:2027")?.nextValue,2);assert.equal(counters.find(x=>x.key==="journal:2026")?.nextValue,counter2026)});
test("GLF-19 manual idempotency",async()=>{const e=await ready(),cash=await account(e,"1110"),sales=await account(e,"4100"),base={branchId:e.branchId,date:"2026-01-01",requestId:"normalized-retry",lines:[{accountId:cash,debit:100,credit:0,description:"  تحصيل   نقدي  "},{accountId:sales,debit:0,credit:100,description:"  بيع   نقدي  "}]};const first=await e.t.mutation(api.generalLedger.postManualJournal,{...base,memo:"  قيد   نقدي  "}),stable=await snapshot(e),retry=await e.t.mutation(api.generalLedger.postManualJournal,{...base,memo:"قيد نقدي",lines:[{...base.lines[0],description:"تحصيل نقدي"},{...base.lines[1],description:"بيع نقدي"}]});assert.equal(retry._id,first._id);assert.equal(retry.entryNumber,first.entryNumber);assert.deepEqual(await snapshot(e),stable);assert.equal(stable.journalLines.length,2);assert.equal(stable.generalLedgerAccountBalances.length,2);assert.equal(stable.generalLedgerPeriodBalances.length,2);assert.equal(stable.documentCounters[0].nextValue,2);assert.equal(stable.auditLogs.filter(x=>x.action==="post").length,1);assert.equal(stable.payments.length,0)});
test("GLF-20 manual fingerprint conflict",async()=>{const e=await ready(),cash=await account(e,"1110"),sales=await account(e,"4100"),receivable=await account(e,"1200"),base={branchId:e.branchId,date:"2026-01-01",memo:"base memo",requestId:"fingerprint-conflict",lines:[{accountId:cash,debit:100,credit:0,description:"cash"},{accountId:sales,debit:0,credit:100,description:"sale"}]};await e.t.mutation(api.generalLedger.postManualJournal,base);const reject=async(change:typeof base)=>rejectUnchanged(e,e.t.mutation(api.generalLedger.postManualJournal,change),/حمولة مختلفة/);await reject({...base,lines:[{...base.lines[0],debit:101},{...base.lines[1],credit:101}]});await reject({...base,date:"2026-01-02"});await reject({...base,lines:[{...base.lines[0],accountId:receivable},base.lines[1]]});await reject({...base,memo:"changed memo"});await reject({...base,lines:[{...base.lines[0],description:"changed description"},base.lines[1]]});const stable=await snapshot(e);assert.equal(stable.journalEntries.length,1);assert.equal(stable.journalLines.length,2);assert.equal(stable.generalLedgerAccountBalances.length,2);assert.equal(stable.generalLedgerPeriodBalances.length,2);assert.equal(stable.documentCounters[0].nextValue,2);assert.equal(stable.auditLogs.filter(x=>x.action==="post").length,1);assert.equal(stable.payments.length,0)});
test("GLF-21 closed period posting rejection",async()=>{const e=await ready();await post(e,"before-close",undefined,100);await e.t.mutation(api.generalLedger.closePeriod,{periodKey:"2026-01",reason:"إغلاق يناير"});const stable=await snapshot(e);await assert.rejects(post(e,"closed-period","2026-01-02",40),/مفتوحة/);assert.deepEqual(await snapshot(e),stable)});
test("GLF-22 balanced period close audit",async()=>{const e=await ready();await post(e,"close-100","2026-01-02",100);await post(e,"close-40","2026-01-03",40);const before=await snapshot(e);const id=await e.t.mutation(api.generalLedger.closePeriod,{periodKey:"2026-01",reason:"  إغلاق   فعلي  "});const period=await e.raw.run(c=>c.db.get(id)),after=await snapshot(e),periodBalances=after.generalLedgerPeriodBalances.filter(x=>x.periodKey==="2026-01");assert.deepEqual({status:period?.status,reason:period?.closeReason,closedBy:period?.closedBy},{status:"closed",reason:"إغلاق فعلي",closedBy:"admin"});assert.ok(period?.closedAt);assert.equal(periodBalances.reduce((s,x)=>s+x.debitTotal,0),140);assert.equal(periodBalances.reduce((s,x)=>s+x.creditTotal,0),140);assert.equal(after.auditLogs.filter(x=>x.action==="close_period").length,before.auditLogs.filter(x=>x.action==="close_period").length+1);const stable=await snapshot(e);await assert.rejects(e.t.mutation(api.generalLedger.closePeriod,{periodKey:"2026-01",reason:"إغلاق ثان"}));assert.deepEqual(await snapshot(e),stable)});
test("GLF-23 authorized reopen with reason",async()=>{const e=await ready();await post(e,"reopen-source");await e.t.mutation(api.generalLedger.closePeriod,{periodKey:"2026-01",reason:"إغلاق"});const accountant=await addUser(e,"accountant","accountant"),manager=await addUser(e,"manager","manager");await rejectUnchanged(e,accountant.mutation(api.generalLedger.reopenPeriod,{periodKey:"2026-01",reason:"  "}));await rejectUnchanged(e,manager.mutation(api.generalLedger.reopenPeriod,{periodKey:"2026-01",reason:"غير مصرح"}));const id=await accountant.mutation(api.generalLedger.reopenPeriod,{periodKey:"2026-01",reason:"  تصحيح   معتمد "});const period=await e.raw.run(c=>c.db.get(id));assert.deepEqual({status:period?.status,reason:period?.reopenReason,by:period?.reopenedBy},{status:"open",reason:"تصحيح معتمد",by:"accountant"});assert.ok(period?.reopenedAt);await postAt(e,e.branchId,"after-reopen","2026-01-03",25,accountant);const stable=await snapshot(e);await assert.rejects(accountant.mutation(api.generalLedger.reopenPeriod,{periodKey:"2026-01",reason:"مرة أخرى"}));assert.deepEqual(await snapshot(e),stable)});
test("GLF-24 actual reversal balance update",async()=>{const e=await ready();const original=await post(e,"original-120","2026-01-02",120),reversal=await e.t.mutation(api.generalLedger.reverseJournal,{entryId:original._id,reversalDate:"2026-01-03",reason:"تصحيح 120",requestId:"reverse-120"});const state=await snapshot(e),storedOriginal=state.journalEntries.find(x=>x._id===original._id),storedReversal=state.journalEntries.find(x=>x._id===reversal._id);assert.deepEqual([original.entryNumber,reversal.entryNumber],["JRN-2026-00001","JRN-2026-00002"]);assert.equal(storedOriginal?.status,"reversed");assert.equal(storedOriginal?.reversalEntryId,reversal._id);assert.equal(storedReversal?.originalEntryId,original._id);assert.deepEqual(state.journalLines.map(x=>[x.debit,x.credit]),[[120,0],[0,120],[0,120],[120,0]]);assert.ok(state.generalLedgerAccountBalances.every(x=>x.netDebitBalance===0));assert.ok(state.generalLedgerPeriodBalances.every(x=>x.netDebitMovement===0));assert.ok(state.generalLedgerDailyBalances.some(x=>x.entryDate==="2026-01-03"));assert.equal(state.payments.length,0)});
