test("GLF-26 closed original reversed later",async()=>{const e=await ready();const original=await post(e,"jan-100","2026-01-10",100);await e.t.mutation(api.generalLedger.closePeriod,{periodKey:"2026-01",reason:"إغلاق يناير"});await e.t.mutation(api.generalLedger.createOrOpenPeriod,{periodKey:"2026-02"});const reversal=await e.t.mutation(api.generalLedger.reverseJournal,{entryId:original._id,reversalDate:"2026-02-01",reason:"عكس فبراير",requestId:"feb-reverse"}),jan=await e.t.query(api.generalLedger.trialBalance,{branchId:e.branchId,periodKey:"2026-01"}),feb=await e.t.query(api.generalLedger.trialBalance,{branchId:e.branchId,periodKey:"2026-02"}),periods=await e.t.query(api.generalLedger.periods,{});assert.equal(periods.find(x=>x.periodKey==="2026-01")?.status,"closed");assert.equal(reversal.periodKey,"2026-02");assert.deepEqual(jan.find(x=>x.code==="1110"),{code:"1110",nameAr:"خزائن نقدية",normalSide:"debit",openingDebit:0,openingCredit:0,periodDebit:100,periodCredit:0,closingDebit:100,closingCredit:0});assert.equal(feb.find(x=>x.code==="1110")?.openingDebit,100);assert.equal(feb.find(x=>x.code==="1110")?.periodCredit,100);assert.equal(feb.find(x=>x.code==="1110")?.closingDebit,0);assert.equal(feb.find(x=>x.code==="4100")?.closingCredit,0)});
