test("GLF-28 posted entry immutable API",async()=>{const e=await ready(),entry=await post(e,"immutable"),stable=await snapshot(e),details=await e.t.query(api.generalLedger.entryDetails,{entryId:entry._id}),print=await e.t.query(api.generalLedger.entryForPrint,{entryId:entry._id});assert.equal(details.entryNumber,entry.entryNumber);assert.equal(print.entryNumber,entry.entryNumber);await assert.rejects(e.t.mutation(api.generalLedger.reverseJournal,{entryId:entry._id,reversalDate:"2026-01-02",reason:" ",requestId:"invalid-empty"}));assert.deepEqual(await snapshot(e),stable);const reversal=await e.t.mutation(api.generalLedger.reverseJournal,{entryId:entry._id,reversalDate:"2026-01-02",reason:"العكس الوحيد",requestId:"immutable-reverse"}),after=await snapshot(e);await assert.rejects(e.t.mutation(api.generalLedger.reverseJournal,{entryId:reversal._id,reversalDate:"2026-01-03",reason:"عكس العكس",requestId:"reverse-reversal"}));assert.deepEqual(await snapshot(e),after)});
test("GLF-29 manager branch query isolation",async()=>{const e=await ready(),other=await addBranch(e,"فرع المدير الآخر"),firstEntry=await postAt(e,e.branchId,"manager-first","2026-01-02",100),otherEntry=await postAt(e,other,"manager-other","2026-01-03",70),manager=await addUser(e,"manager","manager",e.branchId),cash=await account(e,"1110"),before=await snapshot(e);const entries=await manager.query(api.generalLedger.entriesPaginated,{branchId:other,from:"2026-01-01",to:"2026-01-31",paginationOpts:page}),ledger=await manager.query(api.generalLedger.accountLedgerPaginated,{branchId:other,accountId:cash,from:"2026-01-01",to:"2026-01-31",paginationOpts:page}),trial=await manager.query(api.generalLedger.trialBalance,{branchId:other,periodKey:"2026-01"});assert.deepEqual(entries.page.map(x=>x._id),[firstEntry._id]);assert.deepEqual(ledger.page.map(x=>x.runningBalance),[100]);assert.equal(trial.find(x=>x.code==="1110")?.closingDebit,100);assert.equal(entries.page.some(x=>x._id===otherEntry._id),false);await assert.rejects(manager.query(api.generalLedger.entryDetails,{entryId:otherEntry._id}));await assert.rejects(manager.query(api.generalLedger.entryForPrint,{entryId:otherEntry._id}));await assert.rejects(postAt(e,e.branchId,"manager-write","2026-01-04",10,manager));assert.deepEqual(await snapshot(e),before)});
test("GLF-30 admin accountant two branches",async()=>{const e=await ready(),other=await addBranch(e,"فرع المحاسب"),accountant=await addUser(e,"accountant","accountant"),admin=await addUser(e,"second-admin","admin"),first=await postAt(e,e.branchId,"admin-first","2026-01-02",90,admin),second=await postAt(e,other,"accountant-second","2026-01-03",60,accountant),cash=await account(e,"1110");const adminFirst=await admin.query(api.generalLedger.entriesPaginated,{branchId:e.branchId,from:"2026-01-01",to:"2026-01-31",paginationOpts:page}),adminSecond=await admin.query(api.generalLedger.entriesPaginated,{branchId:other,from:"2026-01-01",to:"2026-01-31",paginationOpts:page}),accountantFirst=await accountant.query(api.generalLedger.accountLedgerPaginated,{branchId:e.branchId,accountId:cash,from:"2026-01-01",to:"2026-01-31",paginationOpts:page}),accountantSecond=await accountant.query(api.generalLedger.trialBalance,{branchId:other,periodKey:"2026-01"});assert.deepEqual(adminFirst.page.map(x=>x._id),[first._id]);assert.deepEqual(adminSecond.page.map(x=>x._id),[second._id]);assert.deepEqual(accountantFirst.page.map(x=>x.runningBalance),[90]);assert.equal(accountantSecond.find(x=>x.code==="1110")?.closingDebit,60);assert.equal((await accountant.query(api.generalLedger.entryDetails,{entryId:first._id})).entryNumber,first.entryNumber);assert.equal((await admin.query(api.generalLedger.entryForPrint,{entryId:second._id})).entryNumber,second.entryNumber)});
test("GLF-31 unauthorized roles no effects",async()=>{const e=await ready(),entry=await post(e,"protected"),identities=await Promise.all([addUser(e,"viewer","viewer"),addUser(e,"sales","sales"),addUser(e,"shipping","shipping")]);const stable=await snapshot(e);for(const identity of identities){await assert.rejects(identity.query(api.generalLedger.entriesPaginated,{from:"2026-01-01",to:"2026-01-31",paginationOpts:page}));await assert.rejects(identity.query(api.generalLedger.entryForPrint,{entryId:entry._id}));await assert.rejects(identity.mutation(api.generalLedger.postManualJournal,{branchId:e.branchId,date:"2026-01-02",memo:"مرفوض",requestId:`deny-${Math.random()}`,lines:[{accountId:await account(e,"1110"),debit:1,credit:0},{accountId:await account(e,"4100"),debit:0,credit:1}]}));await assert.rejects(identity.mutation(api.generalLedger.reverseJournal,{entryId:entry._id,reversalDate:"2026-01-02",reason:"مرفوض",requestId:`deny-reverse-${Math.random()}`}));await assert.rejects(identity.mutation(api.generalLedger.closePeriod,{periodKey:"2026-01",reason:"مرفوض"}));await assert.rejects(identity.mutation(api.generalLedger.reopenPeriod,{periodKey:"2026-01",reason:"مرفوض"}));}assert.deepEqual(await snapshot(e),stable)});
test("GLF-32 entry pagination no leaks",async()=>{const e=await ready(),other=await addBranch(e,"فرع الصفحات");for(let i=1;i<=5;i++)await postAt(e,e.branchId,`page-first-${i}`,`2026-01-0${i+1}`,i*10);for(let i=1;i<=2;i++)await postAt(e,other,`page-other-${i}`,`2026-01-0${i+1}`,i*7);const manager=await addUser(e,"manager-pages","manager",e.branchId),seen:string[]=[],numbers:string[]=[],cursors:string[]=[];let cursor:string|null=null;do{const result=await manager.query(api.generalLedger.entriesPaginated,{branchId:other,from:"2026-01-01",to:"2026-01-31",paginationOpts:{numItems:1,cursor}});for(const row of result.page){assert.deepEqual(keys(row),["_id","date","entryNumber","lineCount","memo","sourceType","status","totalCredit","totalDebit"]);seen.push(String(row._id));numbers.push(row.entryNumber)}if(!result.isDone)cursors.push(result.continueCursor);cursor=result.isDone?null:result.continueCursor}while(cursor);assert.equal(seen.length,5);assert.equal(new Set(seen).size,5);assert.equal(new Set(cursors).size,cursors.length);assert.deepEqual(numbers,[...numbers].sort().reverse());const adminOther=await e.t.query(api.generalLedger.entriesPaginated,{branchId:other,from:"2026-01-01",to:"2026-01-31",paginationOpts:page});assert.equal(adminOther.page.length,2);assert.equal(adminOther.page.some(x=>seen.includes(String(x._id))),false)});
test("GLF-33 account ledger pagination running balance",async()=>{const e=await initialized();await e.t.mutation(api.generalLedger.createOrOpenPeriod,{periodKey:"2026-01"});const cash=await account(e,"1110"),sales=await account(e,"4100"),expense=await account(e,"6200"),capital=await account(e,"3200");await e.t.mutation(api.generalLedger.confirmOpening,{branchId:e.branchId,openingDate:"2026-01-01",isZeroOpening:false,requestId:"ledger-opening-1000",lines:[{accountId:cash,debit:1000,credit:0},{accountId:capital,debit:0,credit:1000}]});await postAt(e,e.branchId,"ledger-plus-100","2026-01-10",100);await e.t.mutation(api.generalLedger.postManualJournal,{branchId:e.branchId,date:"2026-01-20",memo:"ناقص 30",requestId:"ledger-minus-30",lines:[{accountId:expense,debit:30,credit:0},{accountId:cash,debit:0,credit:30}]});await postAt(e,e.branchId,"ledger-plus-50","2026-01-25",50);await postAt(e,e.branchId,"ledger-backdated-20","2026-01-15",20);await e.raw.run(async c=>{for(const row of await c.db.query("generalLedgerDailyBalances").collect())await c.db.delete(row._id)});let cursor:string|null=null;const running:number[]=[],beforePages:number[]=[],dates:string[]=[];do{const result=await e.t.query(api.generalLedger.accountLedgerPaginated,{branchId:e.branchId,accountId:cash,from:"2026-01-01",to:"2026-01-31",paginationOpts:{numItems:1,cursor}});for(const row of result.page){assert.deepEqual(keys(row),["credit","date","debit","description","entryNumber","lineNumber","runningBalance","sourceType","status"]);running.push(row.runningBalance);dates.push(row.date)}if(result.page.length)beforePages.push(result.balanceBeforePage);cursor=result.isDone?null:result.continueCursor}while(cursor);assert.deepEqual(dates,["2026-01-01","2026-01-10","2026-01-15","2026-01-20","2026-01-25"]);assert.deepEqual(running,[1000,1100,1120,1090,1140]);assert.deepEqual(beforePages,[0,1000,1100,1120,1090]);const ranged=await e.t.query(api.generalLedger.accountLedgerPaginated,{branchId:e.branchId,accountId:cash,from:"2026-01-10",to:"2026-01-31",paginationOpts:page}),creditLedger=await e.t.query(api.generalLedger.accountLedgerPaginated,{branchId:e.branchId,accountId:sales,from:"2026-01-01",to:"2026-01-31",paginationOpts:page});assert.equal(ranged.openingBalance,1000);assert.deepEqual(ranged.page.map(x=>x.runningBalance),[1100,1120,1090,1140]);assert.deepEqual(creditLedger.page.map(x=>x.runningBalance),[100,120,170])});
