type BridgeAccountIds={cash:Id<"financialAccounts">;bank:Id<"financialAccounts">;wallet:Id<"financialAccounts">;cod:Id<"financialAccounts">};
async function bridgeSetup(options:{activationDate?:string;financeCutover?:string;enable?:boolean;matchingOpening?:boolean}={}){
 const activationDate=options.activationDate??"2026-01-01",e=await fixture();
 await e.t.mutation(api.generalLedger.initialize,{cutoverDate:"2025-01-01",requestId:"bridge-init"});
 await e.t.mutation(api.generalLedger.createOrOpenPeriod,{periodKey:activationDate.slice(0,7)});
 await e.t.mutation(api.finance.configureInitialization,{cutoverDate:options.financeCutover??"2025-01-01",defaultClearingDelayDays:1});
 const cash=await e.t.mutation(api.finance.createAccount,{name:"الخزينة",code:"CASH",type:"cash",branchId:e.branchId});
 const bank=await e.t.mutation(api.finance.createAccount,{name:"البنك",code:"BANK",type:"bank",branchId:e.branchId});
 const wallet=await e.t.mutation(api.finance.createAccount,{name:"Paymob",code:"PAY",type:"paymob_clearing",branchId:e.branchId,settlementDelayDays:0});
 await e.t.mutation(api.finance.postOpeningBalance,{accountId:cash,amount:100,date:activationDate,requestId:"cash-opening"});
 await e.t.mutation(api.finance.postOpeningBalance,{accountId:bank,amount:50,date:activationDate,requestId:"bank-opening"});
 await e.t.mutation(api.finance.postOpeningBalance,{accountId:wallet,amount:80,date:activationDate,requestId:"wallet-opening"});
 const cod=await e.raw.run(c=>c.db.insert("financialAccounts",{name:"COD",code:"COD",uniqueKey:`${e.branchId}:COD`,type:"cod_clearing",branchId:e.branchId,isActive:true,currentBalance:0,allowNegative:false,settlementDelayDays:0,createdAt:1,createdBy:"admin",updatedAt:1,openingBalancePostedAt:1}));
 await e.t.mutation(api.finance.confirmInitialization,{});
 const matching=options.matchingOpening!==false;
 await e.t.mutation(api.generalLedger.confirmOpening,{branchId:e.branchId,openingDate:activationDate,isZeroOpening:!matching,requestId:"bridge-opening",lines:matching?[
  {accountId:await account(e,"1110"),debit:100,credit:0},
  {accountId:await account(e,"1120"),debit:50,credit:0},
  {accountId:await account(e,"1130"),debit:80,credit:0},
  {accountId:await account(e,"3200"),debit:0,credit:230},
 ]:[]});
 if(options.enable!==false)await e.t.mutation(api.generalLedger.enableFinancialPosting,{cutoverDate:activationDate,requestId:"enable-financial"});
 return{...e,activationDate,accounts:{cash,bank,wallet,cod}as BridgeAccountIds};
}
async function bridgeSnapshot(e:Awaited<ReturnType<typeof bridgeSetup>>){return e.raw.run(async c=>{const sort=<T extends{_id:string}>(rows:T[])=>rows.sort((a,b)=>String(a._id).localeCompare(String(b._id)));return{financialAccounts:sort(await c.db.query("financialAccounts").collect()),financialTransactions:sort(await c.db.query("financialTransactions").collect()),financialMovements:sort(await c.db.query("financialMovements").collect()),journalEntries:sort(await c.db.query("journalEntries").collect()),journalLines:sort(await c.db.query("journalLines").collect()),generalLedgerAccountBalances:sort(await c.db.query("generalLedgerAccountBalances").collect()),generalLedgerPeriodBalances:sort(await c.db.query("generalLedgerPeriodBalances").collect()),generalLedgerDailyBalances:sort(await c.db.query("generalLedgerDailyBalances").collect()),documentCounters:sort(await c.db.query("documentCounters").collect()),auditLogs:sort(await c.db.query("auditLogs").collect()),payments:sort(await c.db.query("payments").collect())}})}
async function bridgePost(e:Awaited<ReturnType<typeof bridgeSetup>>,type:"invoice_payment"|"invoice_refund"|"order_deposit"|"order_refund"|"repair_payment"|"repair_refund"|"expense_payment"|"supplier_payment"|"supplier_refund"|"delivery_cod_collection"|"sales_return_refund"|"clearing_settlement"|"cod_settlement",requestId:string,accountId:Id<"financialAccounts">,signedAmount:number,amount=Math.abs(signedAmount),feeAmount=0){return e.t.mutation(api.financialBridgeHarness.post,{type,requestId,date:e.activationDate,amount,feeAmount,description:`اختبار ${requestId}`,branchId:e.branchId,movements:[{accountId,signedAmount}]})}
async function bridgeJournal(e:Awaited<ReturnType<typeof bridgeSetup>>,transactionId:Id<"financialTransactions">){return e.raw.run(async c=>{const entry=await c.db.query("journalEntries").withIndex("by_financial_transaction",q=>q.eq("financialTransactionId",transactionId)).unique();assert.ok(entry);const lines=await c.db.query("journalLines").withIndex("by_entry",q=>q.eq("entryId",entry._id)).collect();return{entry,lines:lines.sort((a,b)=>a.lineNumber-b.lineNumber)}})}
function lineAmounts(lines:Array<{accountCodeSnapshot:string;debit:number;credit:number}>){return lines.map(line=>[line.accountCodeSnapshot,line.debit,line.credit]as const).sort((a,b)=>a[0].localeCompare(b[0]))}

test("FGB-01 readiness reports missing finance initialization",async()=>{const e=await initialized("2025-01-01");await e.t.mutation(api.generalLedger.createOrOpenPeriod,{periodKey:"2026-01"});const readiness=await e.t.query(api.generalLedger.financialPostingReadinessStatus,{cutoverDate:"2026-01-01"});assert.equal(readiness.ready,false);assert.ok(readiness.issues.some(x=>x.includes("دفتر الخزائن")));assert.equal(readiness.requiredSystemAccounts,12)});
