test("FGB-03 activation stores cutover while full operational posting stays disabled",async()=>{const e=await bridgeSetup(),status=await e.t.query(api.generalLedger.status,{});assert.equal(status.financialPostingEnabled,true);assert.equal(status.financialPostingCutoverDate,"2026-01-01");assert.equal(status.operationalPostingEnabled,false);assert.ok(status.financialPostingActivatedAt)});
test("FGB-04 activation retry is idempotent and conflicting request is rejected",async()=>{const e=await bridgeSetup(),first=await e.t.mutation(api.generalLedger.enableFinancialPosting,{cutoverDate:e.activationDate,requestId:"enable-financial"}),before=await bridgeSnapshot(e),retry=await e.t.mutation(api.generalLedger.enableFinancialPosting,{cutoverDate:e.activationDate,requestId:"enable-financial"});assert.deepEqual(retry,first);assert.deepEqual(await bridgeSnapshot(e),before);await assert.rejects(e.t.mutation(api.generalLedger.enableFinancialPosting,{cutoverDate:e.activationDate,requestId:"different"}),/طلب مختلف/)});
test("FGB-05 activation requires initialization permission",async()=>{const e=await bridgeSetup({enable:false}),manager=await addUser(e,"bridge-manager","manager",e.branchId);await assert.rejects(manager.mutation(api.generalLedger.enableFinancialPosting,{cutoverDate:e.activationDate,requestId:"manager-enable"}),/صلاحية/)});
test("FGB-06 same-branch transfer posts one balanced financial journal",async()=>{const e=await bridgeSetup(),transactionId=await e.t.mutation(api.finance.transferFunds,{sourceAccountId:e.accounts.cash,destinationAccountId:e.accounts.bank,amount:20,date:e.activationDate,requestId:"transfer-20"}),journal=await bridgeJournal(e,transactionId);assert.deepEqual(lineAmounts(journal.lines),[["1110",0,20],["1120",20,0]]);assert.equal(journal.entry.sourceType,"financial");assert.equal(journal.entry.operationType,"account_transfer");assert.equal(journal.entry.totalDebit,20);assert.equal(journal.entry.totalCredit,20)});
test("FGB-07 financial retry returns one transaction and rejects changed fingerprint",async()=>{const e=await bridgeSetup(),args={sourceAccountId:e.accounts.cash,destinationAccountId:e.accounts.bank,amount:20,date:e.activationDate,requestId:"transfer-retry"},first=await e.t.mutation(api.finance.transferFunds,args),retry=await e.t.mutation(api.finance.transferFunds,args),stable=await bridgeSnapshot(e);assert.equal(first,retry);assert.equal(stable.financialTransactions.filter(x=>x.type==="account_transfer").length,1);assert.equal(stable.journalEntries.filter(x=>x.financialTransactionId===first).length,1);await assert.rejects(e.t.mutation(api.finance.transferFunds,{...args,amount:21}),/حركة مالية مختلفة/);assert.deepEqual(await bridgeSnapshot(e),stable)});
test("FGB-08 cross-branch transfer rolls back balances transaction and journal",async()=>{const e=await bridgeSetup(),other=await e.raw.run(c=>c.db.insert("branches",{name:"الثاني",address:"جيزة",isActive:true})),otherBank=await e.raw.run(c=>c.db.insert("financialAccounts",{name:"بنك ثان",code:"B2",uniqueKey:`${other}:B2`,type:"bank",branchId:other,isActive:true,currentBalance:0,allowNegative:false,settlementDelayDays:0,createdAt:1,createdBy:"admin",updatedAt:1,openingBalancePostedAt:1})),before=await bridgeSnapshot(e);await assert.rejects(e.t.mutation(api.finance.transferFunds,{sourceAccountId:e.accounts.cash,destinationAccountId:otherBank,amount:10,date:e.activationDate,requestId:"cross-branch"}),/بين الفروع/);assert.deepEqual(await bridgeSnapshot(e),before)});
test("FGB-09 invoice collection debits cash and credits receivables",async()=>{const e=await bridgeSetup(),posted=await bridgePost(e,"invoice_payment","invoice-pay",e.accounts.cash,25),journal=await bridgeJournal(e,posted.transactionId);assert.deepEqual(lineAmounts(journal.lines),[["1110",25,0],["1200",0,25]])});
test("FGB-10 invoice refund debits receivables and credits cash",async()=>{const e=await bridgeSetup(),posted=await bridgePost(e,"invoice_refund","invoice-refund",e.accounts.cash,-15),journal=await bridgeJournal(e,posted.transactionId);assert.deepEqual(lineAmounts(journal.lines),[["1110",0,15],["1200",15,0]])});
test("FGB-11 order deposit credits customer advances",async()=>{const e=await bridgeSetup(),posted=await bridgePost(e,"order_deposit","order-deposit",e.accounts.bank,30),journal=await bridgeJournal(e,posted.transactionId);assert.deepEqual(lineAmounts(journal.lines),[["1120",30,0],["2200",0,30]])});
test("FGB-12 order refund debits customer advances",async()=>{const e=await bridgeSetup(),posted=await bridgePost(e,"order_refund","order-refund",e.accounts.cash,-20),journal=await bridgeJournal(e,posted.transactionId);assert.deepEqual(lineAmounts(journal.lines),[["1110",0,20],["2200",20,0]])});
test("FGB-13 repair collection and refund use receivables control",async()=>{const e=await bridgeSetup(),collection=await bridgePost(e,"repair_payment","repair-pay",e.accounts.cash,18),refund=await bridgePost(e,"repair_refund","repair-refund",e.accounts.cash,-8),a=await bridgeJournal(e,collection.transactionId),b=await bridgeJournal(e,refund.transactionId);assert.deepEqual(lineAmounts(a.lines),[["1110",18,0],["1200",0,18]]);assert.deepEqual(lineAmounts(b.lines),[["1110",0,8],["1200",8,0]])});
test("FGB-14 expense payment debits operating expense and credits cash",async()=>{const e=await bridgeSetup(),posted=await bridgePost(e,"expense_payment","expense",e.accounts.cash,-12),journal=await bridgeJournal(e,posted.transactionId);assert.deepEqual(lineAmounts(journal.lines),[["1110",0,12],["6200",12,0]])});
test("FGB-15 supplier payment debits payable and credits bank",async()=>{const e=await bridgeSetup(),posted=await bridgePost(e,"supplier_payment","supplier-pay",e.accounts.bank,-35),journal=await bridgeJournal(e,posted.transactionId);assert.deepEqual(lineAmounts(journal.lines),[["1120",0,35],["2100",35,0]])});
test("FGB-16 supplier cash refund debits cash and credits payable",async()=>{const e=await bridgeSetup(),posted=await bridgePost(e,"supplier_refund","supplier-refund",e.accounts.cash,22),journal=await bridgeJournal(e,posted.transactionId);assert.deepEqual(lineAmounts(journal.lines),[["1110",22,0],["2100",0,22]])});
test("FGB-17 COD confirmation debits carrier receivable and credits customer",async()=>{const e=await bridgeSetup(),posted=await bridgePost(e,"delivery_cod_collection","cod-collect",e.accounts.cod,40),journal=await bridgeJournal(e,posted.transactionId);assert.deepEqual(lineAmounts(journal.lines),[["1140",40,0],["1200",0,40]])});
test("FGB-18 cash sales return debits contra revenue and credits cash",async()=>{const e=await bridgeSetup(),posted=await bridgePost(e,"sales_return_refund","sales-return",e.accounts.cash,-14),journal=await bridgeJournal(e,posted.transactionId);assert.deepEqual(lineAmounts(journal.lines),[["1110",0,14],["4190",14,0]])});
test("FGB-19 Paymob settlement posts net cash fee and clearing credit",async()=>{const e=await bridgeSetup(),transactionId=await e.t.mutation(api.finance.settleClearingAccount,{sourceAccountId:e.accounts.wallet,destinationAccountId:e.accounts.cash,grossAmount:80,feeAmount:7.5,settlementDate:e.activationDate,requestId:"paymob-settle"}),journal=await bridgeJournal(e,transactionId);assert.deepEqual(lineAmounts(journal.lines),[["1110",72.5,0],["1130",0,80],["6100",7.5,0]]);assert.equal(journal.entry.totalDebit,80);assert.equal(journal.entry.totalCredit,80)});
test("FGB-20 zero-fee clearing settlement remains a two-line balanced entry",async()=>{const e=await bridgeSetup(),posted=await e.t.mutation(api.financialBridgeHarness.post,{type:"clearing_settlement",requestId:"zero-fee",date:e.activationDate,amount:20,feeAmount:0,description:"تسوية بلا رسوم",branchId:e.branchId,movements:[{accountId:e.accounts.wallet,signedAmount:-20},{accountId:e.accounts.bank,signedAmount:20}]}),journal=await bridgeJournal(e,posted.transactionId);assert.deepEqual(lineAmounts(journal.lines),[["1120",20,0],["1130",0,20]]);assert.equal(journal.lines.length,2)});
test("FGB-21 COD settlement posts destination net shipping fee and carrier credit",async()=>{const e=await bridgeSetup();await bridgePost(e,"delivery_cod_collection","cod-before-settle",e.accounts.cod,50);const posted=await e.t.mutation(api.financialBridgeHarness.post,{type:"cod_settlement",requestId:"cod-settle",date:e.activationDate,amount:50,feeAmount:5,description:"تسوية COD",branchId:e.branchId,movements:[{accountId:e.accounts.cod,signedAmount:-50},{accountId:e.accounts.cash,signedAmount:45}]}),journal=await bridgeJournal(e,posted.transactionId);assert.deepEqual(lineAmounts(journal.lines),[["1110",45,0],["1140",0,50],["6100",5,0]])});
test("FGB-22 financial reversal swaps exact lines and links both journals",async()=>{const e=await bridgeSetup(),originalTransactionId=await e.t.mutation(api.finance.transferFunds,{sourceAccountId:e.accounts.cash,destinationAccountId:e.accounts.bank,amount:20,date:e.activationDate,requestId:"reverse-source"}),reversalTransactionId=await e.t.mutation(api.finance.reverseTransaction,{transactionId:originalTransactionId,reason:"تصحيح التحويل",date:e.activationDate,requestId:"reverse-transfer"}),original=await bridgeJournal(e,originalTransactionId),reversal=await bridgeJournal(e,reversalTransactionId);assert.equal(original.entry.status,"reversed");assert.equal(original.entry.reversalEntryId,reversal.entry._id);assert.equal(reversal.entry.originalEntryId,original.entry._id);assert.equal(reversal.entry.sourceType,"financial_reversal");assert.deepEqual(lineAmounts(reversal.lines),[["1110",20,0],["1120",0,20]])});
test("FGB-23 financial reversal retry is stable and changed payload is rejected",async()=>{const e=await bridgeSetup(),transactionId=await e.t.mutation(api.finance.transferFunds,{sourceAccountId:e.accounts.cash,destinationAccountId:e.accounts.bank,amount:10,date:e.activationDate,requestId:"retry-reverse-source"}),args={transactionId,reason:"سبب واحد",date:e.activationDate,requestId:"retry-reverse"},first=await e.t.mutation(api.finance.reverseTransaction,args),retry=await e.t.mutation(api.finance.reverseTransaction,args),stable=await bridgeSnapshot(e);assert.equal(first,retry);await assert.rejects(e.t.mutation(api.finance.reverseTransaction,{...args,reason:"سبب آخر"}),/بيانات مختلفة/);assert.deepEqual(await bridgeSnapshot(e),stable)});
test("FGB-24 closed GL period rolls back the complete financial transaction",async()=>{const e=await bridgeSetup();await e.t.mutation(api.generalLedger.closePeriod,{periodKey:"2026-01",reason:"إقفال الاختبار"});const before=await bridgeSnapshot(e);await assert.rejects(e.t.mutation(api.finance.transferFunds,{sourceAccountId:e.accounts.cash,destinationAccountId:e.accounts.bank,amount:5,date:e.activationDate,requestId:"closed-period-transfer"}),/الفترة المالية غير مفتوحة/);assert.deepEqual(await bridgeSnapshot(e),before)});
test("FGB-25 inactive mapped system account rolls back the financial mutation",async()=>{const e=await bridgeSetup(),cashGl=await account(e,"1110");await e.raw.run(c=>c.db.patch(cashGl,{isActive:false}));const before=await bridgeSnapshot(e);await assert.rejects(bridgePost(e,"invoice_payment","inactive-cash-gl",e.accounts.cash,5),/حساب الأستاذ العام/);assert.deepEqual(await bridgeSnapshot(e),before)});
test("FGB-26 posting before financial bridge cutover is rejected atomically",async()=>{const e=await bridgeSetup({activationDate:"2026-01-10",financeCutover:"2025-01-01"}),before=await bridgeSnapshot(e);await assert.rejects(e.t.mutation(api.financialBridgeHarness.post,{type:"invoice_payment",requestId:"before-bridge",date:"2026-01-09",amount:5,feeAmount:0,description:"قبل الربط",branchId:e.branchId,movements:[{accountId:e.accounts.cash,signedAmount:5}]}),/يسبق تاريخ ربط/);assert.deepEqual(await bridgeSnapshot(e),before)});
test("FGB-27 operational entry DTO stays redacted and cannot be reversed manually",async()=>{const e=await bridgeSetup(),posted=await bridgePost(e,"invoice_payment","dto-financial",e.accounts.cash,9),journal=await bridgeJournal(e,posted.transactionId),details=await e.t.query(api.generalLedger.entryDetails,{entryId:journal.entry._id});assert.deepEqual(keys(details),["branchName","date","employeeName","entryNumber","lineCount","lines","memo","sourceType","status","totalCredit","totalDebit"]);assert.equal(JSON.stringify(details).includes(String(posted.transactionId)),false);const stable=await bridgeSnapshot(e);await assert.rejects(e.t.mutation(api.generalLedger.reverseJournal,{entryId:journal.entry._id,reversalDate:e.activationDate,reason:"محاولة يدوية",requestId:"manual-financial-reverse"}),/المستند الأصلي/);assert.deepEqual(await bridgeSnapshot(e),stable)});
test("FGB-28 bridge never writes legacy payments and does not claim full operations",async()=>{const e=await bridgeSetup();await bridgePost(e,"invoice_payment","final-cash",e.accounts.cash,11);await bridgePost(e,"expense_payment","final-expense",e.accounts.cash,-3);const state=await bridgeSnapshot(e),status=await e.t.query(api.generalLedger.status,{});assert.equal(state.payments.length,0);assert.equal(state.financialTransactions.filter(x=>x.type!=="opening_balance").length,2);assert.equal(state.journalEntries.filter(x=>x.sourceType==="financial").length,2);assert.equal(status.financialPostingEnabled,true);assert.equal(status.operationalPostingEnabled,false)});
